package hvac_visibility_priority_supervisor.HVAC_Visibility_Priority_Supervisor

import org.sireum._
import art.Art
import hvac_visibility_priority_supervisor._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun
@msig trait ThermalServiceProposer_supervision_thermalServiceProposer_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.HVACSupervisor_Instance_supervision_thermalServiceProposer)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.HVACSupervisor_Instance_supervision_thermalServiceProposer)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.HVACSupervisor_Instance_supervision_thermalServiceProposer)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.HVACSupervisor_Instance_supervision_thermalServiceProposer)
  }

  /** helper function to set the values of all input ports.
   * @param thermalAssessment payload for data port thermalAssessment
   * @param wasteHeatEligibility payload for data port wasteHeatEligibility
   * @param thermalPath payload for data port thermalPath
   */
  def put_concrete_inputs(thermalAssessment : HVAC_Visibility_Priority_Supervisor.ThermalAssessment,
                          wasteHeatEligibility : HVAC_Visibility_Priority_Supervisor.WasteHeatEligibility.Type,
                          thermalPath : HVAC_Visibility_Priority_Supervisor.ThermalPathReadiness): Unit = {
    put_thermalAssessment(thermalAssessment)
    put_wasteHeatEligibility(wasteHeatEligibility)
    put_thermalPath(thermalPath)
  }


  /** helper function to check ThermalServiceProposer_supervision_thermalServiceProposer's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param thermalProposal method that will be called with the value of the outgoing data
   *        port 'thermalProposal'.
   */
  def check_concrete_output(thermalProposal: HVAC_Visibility_Priority_Supervisor.ThermalProposal => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val thermalProposalValue: HVAC_Visibility_Priority_Supervisor.ThermalProposal = get_thermalProposal().get
    if(!thermalProposal(thermalProposalValue)) {
      testFailures = testFailures :+ st"'thermalProposal' did not match expected: value of the outgoing data port is ${thermalProposalValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_thermalAssessment(value : HVAC_Visibility_Priority_Supervisor.ThermalAssessment): Unit = {
    Art.insertInInfrastructurePort(Arch.HVACSupervisor_Instance_supervision_thermalServiceProposer.operational_api.thermalAssessment_Id, HVAC_Visibility_Priority_Supervisor.ThermalAssessment_Payload(value))
  }

  // setter for in DataPort
  def put_wasteHeatEligibility(value : HVAC_Visibility_Priority_Supervisor.WasteHeatEligibility.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.HVACSupervisor_Instance_supervision_thermalServiceProposer.operational_api.wasteHeatEligibility_Id, HVAC_Visibility_Priority_Supervisor.WasteHeatEligibility_Payload(value))
  }

  // setter for in DataPort
  def put_thermalPath(value : HVAC_Visibility_Priority_Supervisor.ThermalPathReadiness): Unit = {
    Art.insertInInfrastructurePort(Arch.HVACSupervisor_Instance_supervision_thermalServiceProposer.operational_api.thermalPath_Id, HVAC_Visibility_Priority_Supervisor.ThermalPathReadiness_Payload(value))
  }

  // getter for out DataPort
  def get_thermalProposal(): Option[HVAC_Visibility_Priority_Supervisor.ThermalProposal] = {
    val value: Option[HVAC_Visibility_Priority_Supervisor.ThermalProposal] = get_thermalProposal_payload() match {
      case Some(HVAC_Visibility_Priority_Supervisor.ThermalProposal_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port thermalProposal.  Expecting 'HVAC_Visibility_Priority_Supervisor.ThermalProposal_Payload' but received ${v}")
      case _ => None[HVAC_Visibility_Priority_Supervisor.ThermalProposal]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_thermalProposal_payload(): Option[HVAC_Visibility_Priority_Supervisor.ThermalProposal_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.HVACSupervisor_Instance_supervision_thermalServiceProposer.initialization_api.thermalProposal_Id).asInstanceOf[Option[HVAC_Visibility_Priority_Supervisor.ThermalProposal_Payload]]
  }

}
